    private IReadOnlyList<BackupJob>? _jobs;
    private IReadOnlyList<BackupJob> _filteredJobs = [];
    private bool _isLoading = true;
    private bool _apiUnavailable;
    private bool _disposed;
    private const string BackupCreationDeferredMessage = "Backup creation is deferred. EventStore does not yet have an approved backup engine and manifest model.";
    private const string BackupValidationDeferredMessage = "Backup validation is deferred. EventStore does not yet have an approved backup manifest and validation model.";
    private string _apiErrorMessage = "The admin backend service may be unavailable. Check DAPR sidecar connectivity.";
