    // ---- Restore Dialog ----
    private void OpenRestoreDialog(BackupJob job)
    {
        if (_isAnyDialogOpen) { return; }
        _restoreTarget = job;
        _restoreStep = 1;
        _restoreAcknowledged = false;
        _restorePointInTime = null;
        _restorePointInTimeError = null;
        _restoreDryRun = false;
        _restoreInitiatorId = GetRestoreFocusId(job.BackupId);
        _showRestoreDialog = true;
        _pendingShowRestore = true;
    }

    private async Task CloseRestoreDialogAsync()
    {
        if (_restoreDialog is not null) { await _restoreDialog.HideAsync().ConfigureAwait(false); }
        _showRestoreDialog = false;
        await RestoreInitiatorFocusAsync(isRestore: true).ConfigureAwait(false);
    }
    private void GoToRestoreStep2() => _restoreStep = 2;
    private void GoToRestoreStep1() => _restoreStep = 1;

    private async Task OnRestoreConfirm()
    {
        if (_restoreTarget is null) return;

        string confirmationTarget = Text["BackupTarget", _restoreTarget.BackupId];
        if (!ConfirmationFacts.IsExactAndSupportSafe(confirmationTarget))
        {
            await ShowErrorToastBestEffortAsync(Text["ConfirmationUnsafeTarget"]).ConfigureAwait(false);
            await CloseRestoreDialogAndRestoreFocusAsync().ConfigureAwait(false);
            return;
        }

        _isOperating = true;
        StateHasChanged();
        _operationCts?.Cancel();
        _operationCts?.Dispose();
        _operationCts = new CancellationTokenSource();
        try
        {
            DateTimeOffset? pointInTime = null;
            if (!string.IsNullOrWhiteSpace(_restorePointInTime))
            {
                if (DateTimeOffset.TryParse(_restorePointInTime, System.Globalization.CultureInfo.InvariantCulture, System.Globalization.DateTimeStyles.None, out DateTimeOffset parsed))
                {
                    if (parsed > DateTimeOffset.UtcNow)
                    {
                        _restorePointInTimeError = "Point-in-time cannot be in the future.";
                        _isOperating = false;
                        StateHasChanged();
                        await ShowErrorToastBestEffortAsync(_restorePointInTimeError).ConfigureAwait(false);
                        await CloseRestoreDialogAndRestoreFocusAsync().ConfigureAwait(false);
                        return;
                    }

                    pointInTime = parsed;
                    _restorePointInTimeError = null;
                }
                else
                {
                    _restorePointInTimeError = "Invalid date format. Use ISO 8601 (e.g. 2026-03-20T14:30:00Z).";
                    _isOperating = false;
                    StateHasChanged();
                    await ShowErrorToastBestEffortAsync(_restorePointInTimeError).ConfigureAwait(false);
                    await CloseRestoreDialogAndRestoreFocusAsync().ConfigureAwait(false);
                    return;
                }
            }

            _restorePointInTimeError = null;

            AdminOperationResult? result = await BackupApi.TriggerRestoreAsync(
                _restoreTarget.BackupId,
                pointInTime,
                _restoreDryRun,
                _operationCts.Token);

            if (result?.Success == true)
            {
                await ShowSuccessToastBestEffortAsync($"Restore request accepted for backup {TruncateId(_restoreTarget.BackupId)}.").ConfigureAwait(false);
                if (_restoreDialog is not null) { await _restoreDialog.HideAsync().ConfigureAwait(false); }
                _showRestoreDialog = false;
                await LoadDataAsync();
            }
            else
            {
                await ShowErrorToastBestEffortAsync(result?.Message ?? "Failed to start restore.");
            }
        }
        catch (ServiceUnavailableException)
        {
            await ShowErrorToastBestEffortAsync("Admin service unavailable. Try again later.");
        }
        catch (UnauthorizedAccessException)
        {
            await ShowErrorToastBestEffortAsync("Authentication required. Please sign in again.").ConfigureAwait(false);
            await CloseRestoreDialogAndRestoreFocusAsync().ConfigureAwait(false);
        }
        catch (ForbiddenAccessException)
        {
            await ShowErrorToastBestEffortAsync("Access denied. Administrator permission is required.").ConfigureAwait(false);
            await CloseRestoreDialogAndRestoreFocusAsync().ConfigureAwait(false);
        }
        catch (OperationCanceledException)
        {
            // Silently handle cancellation
        }
        finally
        {
            _isOperating = false;
            // Post-await completion path: continuation may resume off the renderer dispatcher.
            await InvokeAsync(StateHasChanged);
        }
    }

    // ---- Export Dialog ----
    private void OpenExportDialog()
    {
        if (_isAnyDialogOpen) { return; }
        _exportTenantId = string.Empty;
        _exportDomain = string.Empty;
        _exportAggregateId = string.Empty;
        _exportFormat = "JSON";
        _showExportDialog = true;
        _pendingShowExport = true;
    }

    private async Task CloseExportDialogAsync()
    {
        if (_exportDialog is not null) { await _exportDialog.HideAsync().ConfigureAwait(false); }
        _showExportDialog = false;
    }

    private async Task OnExportConfirm()
    {
        _isOperating = true;
        StateHasChanged();
        _operationCts?.Cancel();
        _operationCts?.Dispose();
        _operationCts = new CancellationTokenSource();
        try
        {
            StreamExportResult? result = await BackupApi.ExportStreamAsync(
                new StreamExportRequest(
                    _exportTenantId!.Trim(),
                    _exportDomain!.Trim(),
                    _exportAggregateId!.Trim(),
                    _exportFormat),
                _operationCts.Token);

            if (result?.Success == true
                && !string.IsNullOrWhiteSpace(result.Content)
                && !string.IsNullOrWhiteSpace(result.FileName))
            {
                await JSRuntime.InvokeVoidAsync("blazorDownloadFile", result.FileName, result.Content);
                await ShowSuccessToastBestEffortAsync($"Exported {result.EventCount:N0} events.");
                if (_exportDialog is not null) { await _exportDialog.HideAsync().ConfigureAwait(false); }
                _showExportDialog = false;
            }
            else
            {
                await ShowErrorToastBestEffortAsync(result?.ErrorMessage ?? "Stream export failed.");
            }
        }
        catch (ServiceUnavailableException)
        {
            await ShowErrorToastBestEffortAsync("Admin service unavailable. Try again later.");
        }
        catch (OperationCanceledException)
        {
            // Silently handle cancellation
        }
        finally
        {
            _isOperating = false;
            // Post-await completion path: continuation may resume off the renderer dispatcher.
            await InvokeAsync(StateHasChanged);
        }
    }

    // ---- Import Dialog ----
    private void OpenImportDialog()
    {
        if (_isAnyDialogOpen) { return; }
        _importContent = null;
        _importTenantId = null;
        _importDomain = null;
        _importAggregateId = null;
        _importPreview = null;
        _importError = null;
        _importInitiatorId = "backup-import-button";
        _showImportDialog = true;
        _pendingShowImport = true;
    }

    private async Task CloseImportDialogAsync()
    {
        if (_importDialog is not null) { await _importDialog.HideAsync().ConfigureAwait(false); }
        _showImportDialog = false;
        await RestoreInitiatorFocusAsync(isRestore: false).ConfigureAwait(false);
    }

    private async Task OnImportFileSelected(InputFileChangeEventArgs e)
    {
        _importError = null;
        _importPreview = null;
        _importContent = null;
        _importTenantId = null;
        _importDomain = null;
        _importAggregateId = null;

        try
        {
            using System.IO.Stream stream = e.File.OpenReadStream(maxAllowedSize: 10 * 1024 * 1024);
            using System.IO.StreamReader reader = new(stream);
            string content = await reader.ReadToEndAsync();

            // Try to parse for preview
            try
            {
                using System.Text.Json.JsonDocument doc = System.Text.Json.JsonDocument.Parse(content);
                System.Text.Json.JsonElement root = doc.RootElement;
                string? tenantId = root.TryGetProperty("tenantId", out System.Text.Json.JsonElement tid) ? tid.GetString() : null;
                string? domain = root.TryGetProperty("domain", out System.Text.Json.JsonElement dom) ? dom.GetString() : null;
                string? aggregateId = root.TryGetProperty("aggregateId", out System.Text.Json.JsonElement aid) ? aid.GetString() : null;
                bool hasEvents = root.TryGetProperty("events", out System.Text.Json.JsonElement evts)
                    && evts.ValueKind == System.Text.Json.JsonValueKind.Array;

                if (string.IsNullOrWhiteSpace(tenantId) || string.IsNullOrWhiteSpace(domain) || string.IsNullOrWhiteSpace(aggregateId) || !hasEvents)
                {
                    await FailImportFileAsync("Invalid export file format. Expected JSON with tenantId, domain, aggregateId, and an events array.").ConfigureAwait(false);
                    return;
                }

                string confirmationTarget = GetImportConfirmationTarget(tenantId, domain, aggregateId);
                if (!IsExactSupportSafeImportText(tenantId)
                    || !IsExactSupportSafeImportText(domain)
                    || !IsExactSupportSafeImportText(aggregateId)
                    || !IsExactSupportSafeImportText(confirmationTarget))
                {
                    await FailImportFileAsync(Text["BackupImportUnsafeTarget"].Value).ConfigureAwait(false);
                    return;
                }

                _importTenantId = tenantId;
                _importDomain = domain;
                _importAggregateId = aggregateId;
                _importContent = content;
                _importPreview = $"Tenant: {tenantId}\n"
                    + $"Domain: {domain}\n"
                    + $"Aggregate: {aggregateId}\n"
                    + $"Events: {evts.GetArrayLength()}";
            }
            catch (System.Text.Json.JsonException)
            {
                await FailImportFileAsync("Invalid export file format. Expected JSON with tenantId, domain, aggregateId, and an events array.").ConfigureAwait(false);
            }
        }
        catch (Exception ex) when (ex is not OperationCanceledException)
        {
            _ = ex;
            await FailImportFileAsync("Unable to read the selected import file.").ConfigureAwait(false);
        }
    }

    private async Task FailImportFileAsync(string message)
    {
        _importError = message;
        await ShowErrorToastBestEffortAsync(message).ConfigureAwait(false);
        await CloseImportDialogAndRestoreFocusAsync().ConfigureAwait(false);
    }

    private static bool IsExactSupportSafeImportText(string value)
        => ConfirmationFacts.IsExactAndSupportSafe(value);

    private string GetImportConfirmationTarget(string tenantId, string domain, string aggregateId)
        => Text["BackupImportStreamTarget", tenantId, domain, aggregateId].Value;

    private async Task OnImportConfirm()
    {
        if (_importContent is null
            || _importTenantId is null
            || _importDomain is null
            || _importAggregateId is null)
        {
            await CloseImportDialogAndRestoreFocusAsync().ConfigureAwait(false);
            return;
        }

        string confirmationTarget = ImportConfirmationTarget;
        if (!ConfirmationFacts.IsExactAndSupportSafe(confirmationTarget))
        {
            await ShowErrorToastBestEffortAsync(Text["ConfirmationUnsafeTarget"]).ConfigureAwait(false);
            await CloseImportDialogAndRestoreFocusAsync().ConfigureAwait(false);
            return;
        }

        _isOperating = true;
        StateHasChanged();
        _operationCts?.Cancel();
        _operationCts?.Dispose();
        _operationCts = new CancellationTokenSource();
        try
        {
            AdminOperationResult? result = await BackupApi.ImportStreamAsync(
                _importTenantId,
                _importContent,
                _operationCts.Token);

            if (result?.Success == true)
            {
                await ShowSuccessToastBestEffortAsync("Import request accepted.").ConfigureAwait(false);
                if (_importDialog is not null) { await _importDialog.HideAsync().ConfigureAwait(false); }
                _showImportDialog = false;
                await LoadDataAsync();
            }
            else
            {
                await ShowErrorToastBestEffortAsync(result?.Message ?? "Failed to import stream.");
            }
        }
        catch (ServiceUnavailableException)
        {
            await ShowErrorToastBestEffortAsync("Admin service unavailable. Try again later.");
        }
        catch (UnauthorizedAccessException)
        {
            await ShowErrorToastBestEffortAsync("Authentication required. Please sign in again.").ConfigureAwait(false);
            await CloseImportDialogAndRestoreFocusAsync().ConfigureAwait(false);
        }
        catch (ForbiddenAccessException)
        {
            await ShowErrorToastBestEffortAsync("Access denied. Administrator permission is required.").ConfigureAwait(false);
            await CloseImportDialogAndRestoreFocusAsync().ConfigureAwait(false);
        }
        catch (OperationCanceledException)
        {
            // Silently handle cancellation
        }
        finally
        {
            _isOperating = false;
            // Post-await completion path: continuation may resume off the renderer dispatcher.
            await InvokeAsync(StateHasChanged);
        }
    }

    private async Task CloseRestoreDialogAndRestoreFocusAsync()
    {
        if (_restoreDialog is not null)
        {
            await _restoreDialog.HideAsync().ConfigureAwait(false);
        }

        _showRestoreDialog = false;
        await RestoreInitiatorFocusAsync(isRestore: true).ConfigureAwait(false);
    }

    private async Task CloseImportDialogAndRestoreFocusAsync()
    {
        if (_importDialog is not null)
        {
            await _importDialog.HideAsync().ConfigureAwait(false);
        }

        _showImportDialog = false;
        await RestoreInitiatorFocusAsync(isRestore: false).ConfigureAwait(false);
    }

    private async Task RestoreInitiatorFocusAsync(bool isRestore)
    {
        string? focusId = isRestore ? _restoreInitiatorId : _importInitiatorId;
        if (isRestore)
        {
            _restoreInitiatorId = null;
        }
        else
        {
            _importInitiatorId = null;
        }

        await InvokeAsync(StateHasChanged).ConfigureAwait(false);
        await FocusService.RestoreAsync(focusId).ConfigureAwait(false);
    }

    private async Task RestoreCreateInitiatorFocusAsync()
    {
        string? focusId = _createInitiatorId;
        _createInitiatorId = null;
        await InvokeAsync(StateHasChanged).ConfigureAwait(false);
        await FocusService.RestoreAsync(focusId).ConfigureAwait(false);
    }

    private async Task ShowSuccessToastBestEffortAsync(string? message)
    {
        try
        {
            await ToastService.ShowSuccessAsync(message).ConfigureAwait(false);
        }
        catch
        {
            // Toast failures must not block successful operation state transitions.
        }
    }

    private async Task ShowErrorToastBestEffortAsync(string? message)
    {
        try
        {
            await ToastService.ShowErrorAsync(message).ConfigureAwait(false);
        }
        catch
        {
            // Toast failures must not mask operation failures on error paths.
        }
    }

    private async Task ShowWarningToastBestEffortAsync(string? message)
    {
        try
        {
            await ToastService.ShowWarningAsync(message).ConfigureAwait(false);
        }
        catch
        {
            // Toast failures must not mask deferred-operation feedback.
        }
    }

    private static string SelectDeferredResultMessage(string? message, string fallback) =>
        IsDeferredOperationMessage(message) ? message!.Trim() : fallback;

    private static bool IsDeferredOperationMessage(string? message) =>
        !string.IsNullOrWhiteSpace(message)
        && (message.Contains("deferred", StringComparison.OrdinalIgnoreCase)
            || message.Contains("unsupported", StringComparison.OrdinalIgnoreCase)
            || message.Contains("unavailable", StringComparison.OrdinalIgnoreCase));

    public async ValueTask DisposeAsync()
    {
        _disposed = true;
        _loadCts?.Cancel();
        _loadCts?.Dispose();
        _operationCts?.Cancel();
        _operationCts?.Dispose();
        if (_debounceTimer is not null)
        {
            await _debounceTimer.DisposeAsync();
        }
    }

